import { subprocessEnvironment } from '../utils/subprocessEnvironment';
import * as childProcess from 'child_process';
import fs from 'fs';
import os from 'os';
import path from 'path';
import { errorMessage } from '../utils/errorMessage';

export const CLAUDE_ALLOWLIST_ENTRIES = [
  'Bash(rivet *)',
  'Bash(npx -y rivet-design@latest *)',
] as const;

export const CURSOR_ALLOWLIST_ENTRIES = [
  'Shell(rivet)',
  'Shell(npx:-y rivet-design@latest *)',
] as const;

const CURSOR_EDITOR_ALLOWLIST_ENTRIES = [
  'rivet',
  'npx -y rivet-design@latest',
] as const;

const CURSOR_CLI_CONFIG_VERSION = 1;

export const CODEX_RULES_FILENAME = 'rivet.rules';

export const CODEX_RULES_CONTENT = `# Written by \`rivet install codex\`; removed by \`rivet uninstall codex\`.
# Allows the Rivet design CLI to run without per-call approval prompts.
prefix_rule(
    pattern = ["rivet"],
    decision = "allow",
    justification = "Rivet design CLI (installed via rivet install)",
    match = ["rivet status", "rivet variants start --instruction x"],
)

prefix_rule(
    pattern = ["npx", "-y", "rivet-design@latest"],
    decision = "allow",
    justification = "Rivet design CLI via npx (installed via rivet install)",
    match = ["npx -y rivet-design@latest status"],
)
`;

export type AllowlistWriteResult =
  | { ok: true; changed: boolean; verified: boolean }
  | { ok: false; error: string };

export type AllowlistRemoveResult =
  { ok: true; changed: boolean } | { ok: false; error: string };

const readJsonObject = (
  filePath: string,
):
  | { ok: true; value: Record<string, unknown> }
  | { ok: false; error: string } => {
  if (!fs.existsSync(filePath)) {
    return { ok: true, value: {} };
  }
  try {
    const parsed = JSON.parse(fs.readFileSync(filePath, 'utf8'));
    if (
      parsed === null ||
      typeof parsed !== 'object' ||
      Array.isArray(parsed)
    ) {
      return {
        ok: false,
        error: `${filePath} is not a JSON object. Fix or delete it manually, then re-run.`,
      };
    }
    return { ok: true, value: parsed as Record<string, unknown> };
  } catch {
    return {
      ok: false,
      error: `could not parse ${filePath}. Fix or delete it manually, then re-run.`,
    };
  }
};

const writeJsonObject = (
  filePath: string,
  value: Record<string, unknown>,
): void => {
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, JSON.stringify(value, null, 2) + '\n', 'utf8');
};

export const claudeSettingsPath = (homeDir: string = os.homedir()): string =>
  path.join(homeDir, '.claude', 'settings.json');

export const writeClaudeAllowlist = (
  homeDir: string = os.homedir(),
): AllowlistWriteResult => {
  const filePath = claudeSettingsPath(homeDir);
  const parsed = readJsonObject(filePath);
  if (!parsed.ok) return { ok: false, error: parsed.error };

  const settings = parsed.value;
  const permissions =
    settings.permissions !== null &&
    typeof settings.permissions === 'object' &&
    !Array.isArray(settings.permissions)
      ? (settings.permissions as Record<string, unknown>)
      : {};
  const allow = Array.isArray(permissions.allow)
    ? [...(permissions.allow as unknown[])]
    : [];
  const missing = CLAUDE_ALLOWLIST_ENTRIES.filter(
    (entry) => !allow.includes(entry),
  );
  if (missing.length > 0) {
    allow.push(...missing);
  }
  settings.permissions = { ...permissions, allow };

  try {
    writeJsonObject(filePath, settings);
  } catch (err) {
    return { ok: false, error: errorMessage(err) };
  }
  return {
    ok: true,
    changed: missing.length > 0,
    verified: verifyClaudeAllowlist(homeDir),
  };
};

export const removeClaudeAllowlist = (
  homeDir: string = os.homedir(),
): AllowlistRemoveResult => {
  const filePath = claudeSettingsPath(homeDir);
  if (!fs.existsSync(filePath)) return { ok: true, changed: false };
  const parsed = readJsonObject(filePath);
  if (!parsed.ok) return { ok: false, error: parsed.error };

  const settings = parsed.value;
  const permissions =
    settings.permissions !== null &&
    typeof settings.permissions === 'object' &&
    !Array.isArray(settings.permissions)
      ? (settings.permissions as Record<string, unknown>)
      : null;
  if (!permissions || !Array.isArray(permissions.allow)) {
    return { ok: true, changed: false };
  }
  const currentAllow = permissions.allow as unknown[];
  const before = currentAllow.length;
  const remaining = currentAllow.filter(
    (entry) =>
      !(CLAUDE_ALLOWLIST_ENTRIES as readonly unknown[]).includes(entry),
  );
  if (remaining.length === before) {
    return { ok: true, changed: false };
  }
  permissions.allow = remaining;
  try {
    writeJsonObject(filePath, settings);
  } catch (err) {
    return { ok: false, error: errorMessage(err) };
  }
  return { ok: true, changed: true };
};

export const verifyClaudeAllowlist = (
  homeDir: string = os.homedir(),
): boolean => {
  const parsed = readJsonObject(claudeSettingsPath(homeDir));
  if (!parsed.ok) return false;
  const allow = (parsed.value.permissions as { allow?: unknown[] } | undefined)
    ?.allow;
  return (
    Array.isArray(allow) &&
    CLAUDE_ALLOWLIST_ENTRIES.every((entry) => allow.includes(entry))
  );
};

export const cursorPermissionsPath = (homeDir: string = os.homedir()): string => {
  const directory = process.env.CURSOR_CONFIG_DIR;
  if (directory?.trim()) {
    return path.join(directory, 'cli-config.json');
  }
  const xdgDirectory = process.env.XDG_CONFIG_HOME;
  if (xdgDirectory?.trim()) {
    return path.join(xdgDirectory, 'cursor', 'cli-config.json');
  }
  return path.join(homeDir, '.cursor', 'cli-config.json');
};

export const writeCursorAllowlist = (
  homeDir: string = os.homedir(),
): AllowlistWriteResult => {
  const filePath = cursorPermissionsPath(homeDir);
  const parsed = readJsonObject(filePath);
  if (!parsed.ok) return { ok: false, error: parsed.error };

  const settings = parsed.value;
  const permissions =
    settings.permissions !== null &&
    typeof settings.permissions === 'object' &&
    !Array.isArray(settings.permissions)
      ? (settings.permissions as Record<string, unknown>)
      : {};
  const editor =
    settings.editor !== null &&
    typeof settings.editor === 'object' &&
    !Array.isArray(settings.editor)
      ? (settings.editor as Record<string, unknown>)
      : {};
  const allow = Array.isArray(permissions.allow) ? [...permissions.allow] : [];
  const missing = CURSOR_ALLOWLIST_ENTRIES.filter(
    (entry) => !allow.includes(entry),
  );
  const config = {
    ...settings,
    version: settings.version ?? CURSOR_CLI_CONFIG_VERSION,
    editor: { vimMode: false, ...editor },
    permissions: {
      ...permissions,
      allow: [...allow, ...missing],
      deny: permissions.deny ?? [],
    },
  };
  const isChanged = JSON.stringify(config) !== JSON.stringify(settings);

  try {
    writeJsonObject(filePath, config);
  } catch (err) {
    return { ok: false, error: errorMessage(err) };
  }
  return {
    ok: true,
    changed: isChanged,
    verified: verifyCursorAllowlist(homeDir),
  };
};

export const removeCursorAllowlist = (
  homeDir: string = os.homedir(),
): AllowlistRemoveResult => {
  const filePath = cursorPermissionsPath(homeDir);
  if (!fs.existsSync(filePath)) return { ok: true, changed: false };
  const parsed = readJsonObject(filePath);
  if (!parsed.ok) return { ok: false, error: parsed.error };

  const settings = parsed.value;
  const permissions = settings.permissions as { allow?: unknown[] } | undefined;
  if (!permissions || !Array.isArray(permissions.allow)) {
    return { ok: true, changed: false };
  }
  const remaining = permissions.allow.filter(
    (entry) =>
      !(CURSOR_ALLOWLIST_ENTRIES as readonly unknown[]).includes(entry),
  );
  if (remaining.length === permissions.allow.length) {
    return { ok: true, changed: false };
  }
  permissions.allow = remaining;

  try {
    writeJsonObject(filePath, settings);
  } catch (err) {
    return { ok: false, error: errorMessage(err) };
  }
  return { ok: true, changed: true };
};

export const verifyCursorAllowlist = (
  homeDir: string = os.homedir(),
): boolean => {
  const parsed = readJsonObject(cursorPermissionsPath(homeDir));
  if (!parsed.ok) return false;
  const allowlist = (
    parsed.value.permissions as { allow?: unknown[] } | undefined
  )?.allow;
  return (
    Array.isArray(allowlist) &&
    CURSOR_ALLOWLIST_ENTRIES.every((entry) => allowlist.includes(entry))
  );
};

const cursorEditorPermissionsPath = (homeDir: string): string =>
  path.join(homeDir, '.cursor', 'permissions.json');

export const verifyCursorEditorAllowlist = (
  homeDir: string = os.homedir(),
): boolean => {
  const parsed = readJsonObject(cursorEditorPermissionsPath(homeDir));
  if (!parsed.ok) return false;
  const entries = parsed.value.terminalAllowlist;
  return (
    Array.isArray(entries) &&
    CURSOR_EDITOR_ALLOWLIST_ENTRIES.every((entry) => entries.includes(entry))
  );
};

export const removeCursorEditorAllowlist = (
  homeDir: string = os.homedir(),
): AllowlistRemoveResult => {
  const filePath = cursorEditorPermissionsPath(homeDir);
  if (!fs.existsSync(filePath)) return { ok: true, changed: false };
  const parsed = readJsonObject(filePath);
  if (!parsed.ok) return { ok: false, error: parsed.error };
  const entries = parsed.value.terminalAllowlist;
  if (!Array.isArray(entries)) return { ok: true, changed: false };
  const remaining = entries.filter(
    (entry) =>
      !(CURSOR_EDITOR_ALLOWLIST_ENTRIES as readonly unknown[]).includes(entry),
  );
  if (remaining.length === entries.length) return { ok: true, changed: false };
  if (remaining.length > 0) {
    parsed.value.terminalAllowlist = remaining;
  } else {
    delete parsed.value.terminalAllowlist;
  }
  try {
    writeJsonObject(filePath, parsed.value);
    return { ok: true, changed: true };
  } catch (error) {
    return { ok: false, error: errorMessage(error) };
  }
};

export const codexRulesPath = (homeDir: string = os.homedir()): string =>
  path.join(homeDir, '.codex', 'rules', CODEX_RULES_FILENAME);

export const writeCodexRules = (
  homeDir: string = os.homedir(),
): AllowlistWriteResult => {
  const filePath = codexRulesPath(homeDir);
  const existing = fs.existsSync(filePath)
    ? fs.readFileSync(filePath, 'utf8')
    : null;
  if (existing === CODEX_RULES_CONTENT) {
    return { ok: true, changed: false, verified: verifyCodexRules(homeDir) };
  }
  try {
    fs.mkdirSync(path.dirname(filePath), { recursive: true });
    fs.writeFileSync(filePath, CODEX_RULES_CONTENT, 'utf8');
  } catch (err) {
    return { ok: false, error: errorMessage(err) };
  }
  return { ok: true, changed: true, verified: verifyCodexRules(homeDir) };
};

export const removeCodexRules = (
  homeDir: string = os.homedir(),
): AllowlistRemoveResult => {
  const filePath = codexRulesPath(homeDir);
  if (!fs.existsSync(filePath)) return { ok: true, changed: false };
  try {
    fs.unlinkSync(filePath);
  } catch (err) {
    return { ok: false, error: errorMessage(err) };
  }
  return { ok: true, changed: true };
};

export const verifyCodexRules = (
  homeDir: string = os.homedir(),
  execSync: typeof childProcess.execSync = childProcess.execSync,
): boolean => {
  const filePath = codexRulesPath(homeDir);
  if (!fs.existsSync(filePath)) return false;
  try {
    const output = execSync(
      `codex execpolicy check --rules ${JSON.stringify(filePath)} -- rivet status`,
      {
        stdio: ['ignore', 'pipe', 'ignore'],
        encoding: 'utf8',
        env: subprocessEnvironment('verifier'),
      },
    );
    return /"?decision"?\s*[:=]\s*"?allow"?/i.test(output);
  } catch {
    return fs.readFileSync(filePath, 'utf8').includes('pattern = ["rivet"]');
  }
};
